#!/usr/bin/env node
/**
 * Sync Foundry artifact JSON → strongly-typed TypeScript `as const` ABI
 * exports. Mirrors what `wagmi generate` does, but without the extra
 * dependency — we only need viem-compatible ABI literals here.
 *
 * Re-run after `pnpm --filter @ticketpulse/contracts build` if either the
 * `TicketPulseFactory` or `TicketPulseEvent` Solidity files changed.
 *
 * Output: packages/sdk/src/contracts/__generated__/abis.ts
 * .gitignored — regenerated by `pnpm --filter @ticketpulse/sdk codegen`.
 */

import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs'
import { dirname, resolve, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = dirname(fileURLToPath(import.meta.url))
const MONOREPO_ROOT = resolve(__dirname, '../../..')
const SDK_ROOT = resolve(__dirname, '..')

const sources = [
  {
    constName: 'ticketPulseFactoryAbi',
    artifactPath: join(
      MONOREPO_ROOT,
      'packages/contracts/out/TicketPulseFactory.sol/TicketPulseFactory.json',
    ),
  },
  {
    constName: 'ticketPulseEventAbi',
    artifactPath: join(
      MONOREPO_ROOT,
      'packages/contracts/out/TicketPulseEvent.sol/TicketPulseEvent.json',
    ),
  },
]

const outDir = join(SDK_ROOT, 'src/contracts/__generated__')
if (!existsSync(outDir)) mkdirSync(outDir, { recursive: true })

const banner = [
  '// ─── AUTO-GENERATED by scripts/sync-abis.mjs — do NOT edit ───',
  '// Sources:',
  '//   packages/contracts/out/TicketPulseFactory.sol/TicketPulseFactory.json',
  '//   packages/contracts/out/TicketPulseEvent.sol/TicketPulseEvent.json',
  '// Regenerate with: pnpm --filter @ticketpulse/sdk codegen',
  '',
  '',
].join('\n')

let content = banner

for (const { constName, artifactPath } of sources) {
  if (!existsSync(artifactPath)) {
    console.warn(
      `[sync-abis] artifact missing: ${artifactPath}\n` +
        `           run \`pnpm --filter @ticketpulse/contracts build\` first.`,
    )
    // Emit an empty array as a placeholder so the SDK still compiles in
    // environments where the contracts package hasn't been built yet.
    content += `export const ${constName} = [] as const\n\n`
    continue
  }
  const artifact = JSON.parse(readFileSync(artifactPath, 'utf-8'))
  if (!Array.isArray(artifact.abi)) {
    throw new Error(`[sync-abis] ${artifactPath}: missing "abi" array`)
  }
  content += `export const ${constName} = ${JSON.stringify(artifact.abi, null, 2)} as const\n\n`
}

const outFile = join(outDir, 'abis.ts')
writeFileSync(outFile, content)
console.log(`[sync-abis] wrote ${outFile}`)
